import gurobipy as gp
from gurobipy import GRB
table = None
for t in CSVQA_DATA['tables']:
    if t['table_id'] == 'file_0_view_0':
        table = t
        break
if table is None:
    raise RuntimeError('Table file_0_view_0 not found.')
records = table['records']
worker_columns = [col for col in table['columns'] if col != 'Owner']
homeowners = [rec['values']['Owner'] for rec in records]
workers = worker_columns.copy()
if len(workers) != len(homeowners):
    raise ValueError('Number of workers and homeowners must match.')
d_hw = {}
for rec in records:
    h = rec['values']['Owner']
    d_hw[h] = {}
    for w in workers:
        v = rec['values'][w]
        try:
            d_hw[h][w] = float(v)
        except Exception:
            raise ValueError(f'Non-numeric value for d[{h}][{w}]: {v}')
w1 = workers[0]
r = 60.0
T = 10
for w in workers:
    total = sum((d_hw[h][w] for h in homeowners))
    if abs(total - T) > 1e-06:
        raise ValueError(f'Worker {w} has total work days {total}, expected {T}.')
m = gp.Model('mutual_payment_of_wages')
m.Params.MIPGap = 0.0001
p_vars = m.addVars(workers, lb=-GRB.INFINITY, vtype=GRB.CONTINUOUS, obj=0, name='')
p_vars[w1].LB = r
p_vars[w1].UB = r
for w in workers:
    lhs = gp.quicksum((d_hw[h][w] * p_vars[w] for h in homeowners if h != w))
    rhs = gp.quicksum((d_hw[w][w2] * p_vars[w2] for w2 in workers))
    m.addConstr(lhs == rhs, name=f'fairness_{w}')
m.setObjective(0, GRB.MINIMIZE)
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for w in workers:
        print(f'p[{w}]: {p_vars[w].X}')
else:
    print(f'Solver status: {m.Status}')